SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd.name, pd.name_en, pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.status, pd.create_user_id, pd.create_time, pi.spec_type, ps.is_marketable, pd.process_id, pi.property, pi.name_en, pi.brand_name, pi.grade, pd.charge_name AS productChargeName, pd.first_mass_product_date, pd.plan_listing_time, pp.trial_production_qty, pp.ean, pp.delivery_cycle, pp.main_supplier, ps.year_sale_qty, ps.year_sale_amount, ps.listing_time, ps.delisting_time, pi.sales_channel, pi.category, pi.sale_method, ps.sale_state, ppk.box_qty, pp.moq, pl.declare_model, pl.declare_chinese_name, pd.variant_property, pd.unit_name, pd.version, pc.actual_tax_cost, pc.target_tax_cost FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id AND pd.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE LEFT join product_sale ps on pd.id = ps.sku_id AND ps.is_deleted = FALSE left join product_pack ppk on pd.id = ppk.sku_id AND ppk.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id and pl.is_deleted = FALSE WHERE pi.is_deleted = FALSE
AND (pi.spu_no ILIKE concat('%',#{params.no},'%') OR pd.sku_no ILIKE concat('%',#{params.no},'%') OR pd.name ILIKE concat('%', #{params.no},'%'))
AND pd.sku_no ILIKE concat('%',#{params.remoteSearchSku},'%')
AND pd.product_id = #{params.productId}
AND pd.name ILIKE concat('%', #{params.name},'%')
AND pd.is_change = #{params.isChange}
AND pd.status in
#{item}
AND pd.product_state in
#{state}
AND pi.id IN
#{productId}
AND pi.category_id in
#{category}
AND pi.grade_id IN
#{gradeId}
AND ps.sale_state IN
#{saleState}
AND pi.brand_id IN
#{brandId}
AND pi.property_id IN
#{propertyId}
AND pi.project_charge_id IN
#{projectChargeId}
AND
string_to_array(#{chargeId},',') && string_to_array(pi.charge_id,',')
AND pd.charge_id in
#{chargeId}
AND pd.process_id in
#{processId}
AND pi.name ILIKE concat('%',#{params.productName},'%')
AND pd.status IN
#{status}
AND pi.pirate_risk IN
#{pirateRisk}
AND pi.sale_method IN
#{saleMethod}
AND pd.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND pp.main_supplier IN
#{item}
AND pp.ean ILIKE concat('%',#{params.ean},'%')
AND pd.create_time >=#{params.startTime}
AND pd.create_time <= #{params.endTime}
${params.permissionSql}
ORDER BY pd.create_time DESC

SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd.name, pd.name_en, pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.create_user_id, pd.create_time, pi.spec_type, pd.status FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id AND pd.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE WHERE pi.is_deleted = FALSE
AND pi."name" = #{name}
AND pd.sku_no = #{skuNo}
LIMIT 1

SELECT pi.spu_no as spuNo, pd.sku_no as skuNo, pi.category_id AS categoryId, pi.category AS mainCategory, pi.category AS secondaryCategory, pd.charge_name as chargeName, pi.sale_method as saleMethod, pd.name, pd.name_en, pi.property, pi.brand_name as brandName, pd.product_state as productStateName, pi.grade, pi.sales_channel, CASE WHEN pi.is_customized = 1 THEN '是' ELSE '否' END isCustomized, pi.mold_cost, pi.entrusted_develop_cost, pi.sell_spot, pi.function_desc, pi.usage_desc, to_char(pd.plan_listing_time, 'YYYY/MM/dd') AS planListingTime , CASE WHEN pi.pirate_risk = 1 THEN '是' ELSE '否' END pirateRisk, pd.unit_name, pi.materials, pc.project_approval_cost, pc.mass_cost, pc.project_cost, pc.tax_rate, pc.target_tax_cost, pc.target_no_tax_cost, pc.retail_price, pp.ean, pp.moq, pp.trial_production_qty, pp.first_mass_qty, pp.plan_order_qty, pp.actual_arrival_qty, to_char(pp.plan_arrival_time, 'YYYY/MM/dd') AS planArrivalTime , to_char(pp.place_order_time, 'YYYY/MM/dd') AS placeOrderTime , pp.delivery_cycle, pp.purchase_user_id AS purchaseUser, pp.arrival_state, pp.main_supplier, pp.second_supplier, ps.year_sale_qty, ps.year_sale_amount, ps.month_sale_qty, ps.month_sale_amount, ps.target_sales_qty, ps.sale_country, CASE WHEN ps.is_finished_img = 1 THEN '是' ELSE '否' END isFinishedImg, CASE WHEN ps.is_finished_video = 1 THEN '是' ELSE '否' END isFinishedVideo, to_char(ps.delisting_time, 'YYYY/MM/dd') AS delistingTime, ps.sale_state, ps.data_url, CASE WHEN ps.is_marketable = 1 THEN '是' ELSE '否' END isMarketable, ps.sales_platform, pl.product_property, pl.declare_price, pl.declare_chinese_name, pl.declare_english_name, pl.customs_code, pl.declare_model, pl.declare_unit, pl.declare_element, pl.english_material, pl.english_usage, CASE WHEN split_part(ppk.product_size, 'X',1) = '' THEN '0' ELSE split_part(ppk.product_size, 'X',1) END AS productSizeLength, CASE WHEN split_part(ppk.product_size, 'X',2) = '' THEN '0' ELSE split_part(ppk.product_size, 'X',2) END AS productSizeWide, CASE WHEN split_part(ppk.product_size, 'X',3) = '' THEN '0' ELSE split_part(ppk.product_size, 'X',3) END AS productSizeHigh, CASE WHEN split_part(ppk.box_size, 'X',1) = '' THEN '0' ELSE split_part(ppk.box_size, 'X',1) END AS boxSizeLength, CASE WHEN split_part(ppk.box_size, 'X',2) = '' THEN '0' ELSE split_part(ppk.box_size, 'X',2) END AS boxSizeWide, CASE WHEN split_part(ppk.box_size, 'X',3) = '' THEN '0' ELSE split_part(ppk.box_size, 'X',3) END AS boxSizeHigh, ppk.gross_weight, ppk.net_weight, ppk.box_weight, ppk.box_qty, pl.product_property_id, pd.charge_id FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id AND pd.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE LEFT JOIN product_sale ps ON ps.sku_id = pd."id" AND ps.is_deleted = FALSE LEFT JOIN product_pack ppk ON ppk.sku_id = pd."id" AND ppk.is_deleted = FALSE LEFT JOIN product_logistics pl ON pl.sku_id = pd."id" AND pl.is_deleted = FALSE LEFT JOIN product_unit unit ON pd.unit_id = unit.id AND unit.is_deleted = FALSE LEFT JOIN basic_dict dp ON pl.product_property_id = dp.id AND dp.is_deleted = FALSE WHERE pi.is_deleted = FALSE
AND (pi.spu_no ILIKE concat('%',#{params.no},'%') OR pd.sku_no ILIKE concat('%',#{params.no},'%'))
AND pd.product_state in
#{state}
AND pd.id in
#{skuId}

SELECT id,sku_no AS name FROM product_detail


        id IN

            #{skuId}

SELECT pd.version, pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pi.sale_method AS saleMethod, pd.sku_no, pi.spec_type, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property as variantProperty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, pl.product_property_id AS productPropertyId, pi.materials, pi.function_desc, pi.grade AS productGrade, pi.brand_name as brandName, ps.sale_state as saleState, pd.unit_name, pd.status, pp.moq, pp.main_supplier as supplierId, pc.actual_tax_cost, pc.target_tax_cost, pc.retail_price FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE left join product_sale ps on pd.id = ps.sku_id and ps.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE WHERE pi.is_deleted = FALSE AND pd.is_deleted = FALSE
AND pd.status=#{status}
AND pd.sku_no IN
#{sku}

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pi.sale_method, pd.sku_no, pd.images_url, pd.name AS productName, pd.variant_property, pl.declare_chinese_name, pl.declare_model, pi.brand_name, pd.unit_name, pd.status, pp.moq, pp.main_supplier, ppk.box_qty FROM product_detail pd left join product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE left join product_sale ps on pd.id = ps.sku_id and ps.is_deleted = FALSE left join product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE left join product_pack ppk on pd.id = ppk.sku_id AND ppk.is_deleted = FALSE WHERE pd.is_deleted = FALSE
AND pd.status IN
#{item}
AND pd.sku_no IN
#{item}
${params.permissionSql}
ORDER BY pd.create_time DESC

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property, pp.box_qty as unitQty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, pd.unit_name FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_pack pp on pd.id = pp.sku_id AND pp.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE WHERE pd.is_deleted = FALSE
AND pd.status=#{state}
AND ( pd.sku_no ILIKE concat('%',#{searchKeyword},'%') OR pd.name ILIKE concat('%',#{searchKeyword},'%') )

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.name AS skuName FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE WHERE pd.is_deleted = FALSE
AND pd.id IN
#{skuId}

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE WHERE pd.status = #{state} AND pd.is_deleted = FALSE and pd.id not in ( select DISTINCT parent_sku_id from product_bom_sku
is_deleted = false
and bom_id != #{bomId}
)
AND ( pd.sku_no ILIKE concat('%',#{searchKeyword},'%') OR pd.name ILIKE concat('%',#{searchKeyword},'%') )

SELECT pd.version, pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property as variantProperty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, pl.product_property_id AS productPropertyId, pi.materials, pi.function_desc, pi.grade AS productGrade, pi.brand_name as brandName, ps.sale_state as saleState, pd.unit_name, pd.status, pp.moq, pp.main_supplier as supplierId, pd.warehouse_location as warehouseLocation, pi.sale_method, ppk.gross_weight, pc.actual_tax_cost, pc.target_tax_cost, pc.retail_price FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE left join product_sale ps on pd.id = ps.sku_id and ps.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE left join product_pack ppk on pd.id = ppk.sku_id AND ppk.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE WHERE pi.is_deleted = FALSE AND pd.is_deleted = FALSE
AND pd.id IN
#{skuId}

SELECT pd.sku_no, pd.name AS skuName, pi.spu_no, pi.name AS spuName, pd.variant_property, pd.images_url, pp.ean, ppk.gross_weight, ppk.net_weight, ppk.product_size, ppk.box_size, ppk.box_weight, ppk.box_qty, pi.grade, pd.charge_name, pi.materials, t.accessories, pp.main_supplier, pp.second_supplier FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE LEFT JOIN product_purchase pp ON pd.id = pp.sku_id AND pp.is_deleted = FALSE LEFT JOIN product_pack ppk ON pd.id = ppk.sku_id AND ppk.is_deleted = FALSE LEFT JOIN ( SELECT pa.parent_sku_id, array_to_string(ARRAY(SELECT unnest(array_agg(pd.sku_no))),',') AS accessories FROM product_accessories pa LEFT JOIN product_detail pd ON pa.accessories_sku_id = pd.id GROUP BY pa.parent_sku_id )t ON t.parent_sku_id = pd.id WHERE pd.is_deleted = FALSE
AND pd.sku_no = #{skuNo}
LIMIT 1
